package com.aadil.ecommerce.controllers;import com.aadil.ecommerce.dtos.LoginRequestDTO;import com.aadil.ecommerce.enums.UserSortDirection;import com.aadil.ecommerce.enums.UserSortField;import com.aadil.ecommerce.responses.PaginatedResponse;import com.aadil.ecommerce.responses.UserLoginResponse;import com.aadil.ecommerce.services.UserService;import com.aadil.ecommerce.dtos.UserRequestDTO;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.responses.APIResponse;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.io.IOException;import java.io.OutputStream;import java.time.LocalDateTime;import java.util.List;@RestController@RequestMapping("/api/auth")@Validatedpublic class UserController {    private final UserService userService;    public UserController(UserService userService) {        this.userService = userService;    }    @PostMapping("/register")    public ResponseEntity<APIResponse<UserResponseDTO>> register (@Valid @RequestBody UserRequestDTO dto){        UserResponseDTO userResponseDTO = userService.registerUser(dto);        APIResponse<UserResponseDTO> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(201);        apiResponse.setMessage("User registered successfully");        apiResponse.setData(userResponseDTO);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.CREATED);    }   @PostMapping("/login")    public ResponseEntity<APIResponse<UserLoginResponse>> login (@Valid @RequestBody LoginRequestDTO dto){        UserLoginResponse token = userService.userLogin(dto);        APIResponse<UserLoginResponse> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(201);        apiResponse.setMessage("Token Generated Successfully");        apiResponse.setData(token);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CREATED);   }   @GetMapping("/users")    public ResponseEntity<APIResponse<PaginatedResponse<List<UserResponseDTO>>>> getAllUsers (@RequestParam (required = false,name = "Search") String search,                                                                                              @RequestParam (required = false, name = "PageNumber",defaultValue = "0") int pageNumber,                                                                                              @RequestParam (required = false,name = "Size",defaultValue = "10") int size,                                                                                              @RequestParam (required = false,name = "SortField",defaultValue = "ID")UserSortField userSortField,                                                                                              @RequestParam (required = false,name = "SortDirection",defaultValue = "ASC")UserSortDirection sortDirection) throws IOException {        PaginatedResponse<List<UserResponseDTO>> contents = userService.getAllUsers(search,pageNumber,size,userSortField,sortDirection);        APIResponse<PaginatedResponse<List<UserResponseDTO>>> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(200);        apiResponse.setMessage("All Users retrieved successfully");        apiResponse.setData(contents);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.OK);   }}